请对以下 case 进行三维加权评分。

=== case_id ===
Case-19-photo-album-014

=== 用户原始指令 (query.txt) ===
相册仪表盘卡,中心一个环形显示"重复照片326张",下面纵向排三行小数据,每行一个动态数字,红色告警"清理失败"。夜蓝渐变磨砂感,点红色按钮能直接拨我妈电话,顺手读下天气,纯文字色块。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "相册仪表盘卡,中心一个环形显示\"重复照片326张\",下面纵向排三行小数据,每行一个动态数字,红色告警\"清理失败\"。夜蓝渐变磨砂感,点红色按钮能直接拨我妈电话,顺手读下天气,纯文字色块。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToCallPhone",
      "args": {
        "phoneNumber": "13800138000"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "album": {
        "duplicatePhotos": {
          "displayText": {
            "type": "string",
            "description": "重复照片数量展示文本",
            "sampleValue": "重复照片326张"
          },
          "count": {
            "type": "number",
            "description": "重复照片数量，用于环形进度值",
            "sampleValue": 326
          },
          "total": {
            "type": "number",
            "description": "重复照片扫描参考总量，用于环形进度总量",
            "sampleValue": 500
          }
        },
        "metrics": {
          "duplicateGroups": {
            "type": "number",
            "description": "重复照片组数量",
            "sampleValue": 18
          },
          "wastedSpaceGb": {
            "type": "number",
            "description": "重复照片预计占用空间，单位 GB",
            "sampleValue": 4.8
          }
        },
        "cleanupStatus": {
          "type": "string",
          "description": "相册清理任务状态",
          "sampleValue": "清理失败"
        }
      },
      "weather": {
        "current": {
          "temperatureC": {
            "type": "number",
            "description": "当前摄氏温度数值",
            "sampleValue": 29
          }
        }
      }
    },
    "contact": {
      "momPhoneNumber": {
        "type": "string",
        "description": "母亲联系电话，样例为测试号码",
        "sampleValue": "13800138000"
      }
    }
  },
  "assetCandidates": []
}

